def max_Product(arr):
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements to form a pair.")

    # Initialize variables to track the two largest and two smallest values
    max1 = max2 = float('-inf')  # Two largest numbers
    min1 = min2 = float('inf')   # Two smallest numbers (most negative)

    # Traverse the array to find the two largest and two smallest values
    for num in arr:
        # Update largest values
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update smallest values
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compare the products of the two largest and two smallest values
    if max1 * max2 >= min1 * min2:
        return (max2, max1)
    else:
        return (min1, min2)

# Example usage and tests
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([-10, -20, 1, 3, 2]) == (-10, -20)
assert max_Product([5, 6, -3, -2, 0]) == (5, 6)
assert max_Product([-1, -2, -3, -4]) == (-1, -2)
